pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1 wei, 1000 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);
        assertTrue(c.Acc(actor).balance == amount);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(uint _am) public {
        require(_am > 0);
        uint amount = 2 ether;
        require(address(this).balance >= amount);
        c.Put{value: amount}(0);
        c.Collect(_am);
        assert(c.Acc(address(this)) <= amount - _am);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint val, uint _am) public {
        require(address(this).balance >= val, "insufficient eth");
        require(_am > 0 && _am <= val, "bad amount");
        require(val >= c.MinSum(), "below min sum");
        c.Put{value: val}(0);
        c.Collect{value: 0}(_am);
        assert(c.Acc(address(this)).balance == val - _am);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function test(uint _am) public {
        uint amt = _am;
        if (amt == 0) amt = 1;
        require(amt <= 1 ether);
        require(address(this).balance >= amt);
        uint balBefore = address(this).balance;

        c.Put{value: amt}(0);
        require(c.MinSum() <= amt);
        require(c.Acc(address(this)).unlockTime < block.timestamp + 1, "time");

        bool ok1 = true;
        c.Collect(amt);
        bool ok2 = false;
        // after the first withdrawal the balance is zero, so a repeat must not pay
        c.Collect(amt);

        assert(address(this).balance == balBefore - amt && c.Acc(address(this)).balance == 0);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(amount > 0 && amount <= address(c).balance, true == true ? "pre" : "pre");
        uint balBefore = address(c).balance;
        bool reverted;
        try c.Collect{value: 0}(amount) { reverted = false; } catch { reverted = true; }
        if (!reverted) {
            assert(balBefore - address(c).balance == amount);
        } else {
            assert(address(c).balance == balBefore);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint _am) public payable {
        require(address(this).balance >= amount);
        require(_am >= c.MinSum() || true);
        c.Put{value: amount}(0);
        uint balBefore;
        (, balBefore) = c.Acc(address(this));
        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }
        uint balAfter;
        (, balAfter) = c.Acc(address(this));
        if (!reverted) {
            assert(balAfter == balBefore - _am);
        } else {
            assert(balAfter == balBefore);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint am) public payable {
        (uint ut, uint bal) = c.Acc(address(this));
        require(ut < block.timestamp, "unlockTime must have passed");
        require(bal >= am + 1 ether, "balance must cover MinSum and amount");
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
    receive() external payable {}
}
